"""S4: writes docs/VALIDATION.md from results only, so the document cannot disagree with them."""
import json
from pathlib import Path

report = json.loads(Path("results/validation.json").read_text())
fit = json.loads(Path("results/train_fit.json").read_text())
post = json.loads(Path("results/posterior.json").read_text())
s = report["score"]
word = lambda ok: "PASS" if ok else "FAIL"  # noqa: E731
lines = [
    "# Validation report", "",
    "Generated by `scripts/make_validation_doc.py` from `results/`. Do not edit by hand.", "",
    f"Blind: **{report['blind']}** (held-out values opened {report['openings']} time(s); posterior `{report['posterior_sha256'][:12]}`).", "",
    "## Pre-registered checks", "",
    "| Check | What | Result | Detail |", "|---|---|---|---|",
    "| V1 (code check) | Topp equations vs BioModels BIOMD0000000341 in libRoadRunner | see `tests/test_physiology.py` | below 1% is asserted. The simulator uses Topp's fast terms, so this checks transcription only |",
    "| V2 (code check) | Label PK values | see `tests/test_core.py` | within 25% is asserted. Clearance and concentration share a source, so this is weak evidence |",
    f"| V3 | Held-out HbA1c contrasts: MAE <= 0.25 and >= 70% within 0.30 | **{word(s['V3_pass'])}** | MAE {s['mae']}, within 0.30: {s['within_0_30']:.0%}, bias {s['bias']:+} |",
    f"| V4 | 95% predictive interval coverage >= 85% (17 of 20) | **{word(s['V4_pass'])}** | 95%: {s['coverage_95pi']:.0%}, 80%: {s['coverage_80pi']:.0%}, 50%: {s['coverage_50pi']:.0%}, mean width {s['mean_pi95_width']} |",
    f"| V5 | Renal attenuation never fitted: order right, each stratum within 0.30 | **{word(s['V5_pass'])}** | order correct: {s['V5_order_correct']}, each within: {s['V5_each_within']} |",
    f"| V6 | Beat a physiology-free rival that carries training effects forward | **{word(s['beats_null'])}** | model MAE {s['mae']} vs rival {s['null_mae']}; difference {s['model_minus_null_mae']:+} (95% CI {s['model_minus_null_ci95'][0]:+} to {s['model_minus_null_ci95'][1]:+}, by-trial bootstrap) |",
    "", f"Chain converged: **{report['converged']}** (max split R-hat {report['max_split_rhat']:.3f}, chain length {report['length_over_tau']:.0f} autocorrelation times; required below 1.05 and at least 50).", "",
    report["reading_note"], "",
    "## By trial", "", "| Trial | Contrasts | MAE | Rival MAE | Thin pool |", "|---|---:|---:|---:|---|",
    *[f"| {k} | {v['contrasts']} | {v['mae']} | {v['null_mae']} | {'yes' if v['thin_pool'] else 'no'} |" for k, v in report["by_trial"].items()],
    "", "## Assumption sensitivity, no refit", "", "| Change | Largest shift in any contrast |", "|---|---:|",
    *[f"| {k} | {v['largest_shift']} |" for k, v in report["assumption_sensitivity"].items()],
    "", f"Kidney pre-check: urinary glucose relative to normal kidneys in the model is {report['renal_precheck']['model_ratio_mild']} (mild) and {report['renal_precheck']['model_ratio_moderate']} (moderate). {report['renal_precheck']['reference']}",
    "", f"## Held-out contrasts ({s['n_contrasts']})", "",
    "| Trial | Arm vs reference | Predicted | 95% PI | Observed (SE) | Error | Within 0.30 | Covered |", "|---|---|---:|---|---:|---:|---|---|",
]
for r in report["contrasts"]:
    lines.append(f"| {r['trial']} | {r['arm']} vs {r['reference']} | {r['predicted']:+.2f} | {r['pi95'][0]:+.2f} to {r['pi95'][1]:+.2f} | {r['observed']:+.2f} ({r['observed_se']:.2f}) | {r['error']:+.2f} | {'yes' if r['within_0_30'] else 'NO'} | {'yes' if r['covered'] else 'NO'} |")
lines += ["", "## Populations used", "", "| Trial | Eligible real NHANES participants | Effective sample size |", "|---|---:|---:|"]
for name, rep in report["populations"].items():
    lines.append(f"| {name} | {rep['eligible_real_participants']} | {rep['effective_sample_size']} |")
lines += ["", "## Calibration", "", f"{post['walkers']} walkers, {post['steps']} steps, {post['burn']} burn-in, acceptance {post['acceptance']:.2f}.", "",
          "| Parameter | Prior median | Posterior median | 95% interval | Autocorrelation (steps) |", "|---|---:|---:|---|---:|"]
for name, row in post["summary"].items():
    tau = row["autocorr_steps"]
    lines.append(f"| {name} | {row['prior_median']:g} | {row['median']:.4g} | {row['p2_5']:.4g} to {row['p97_5']:.4g} | {tau:.0f} |" if tau else f"| {name} | {row['prior_median']:g} | {row['median']:.4g} | {row['p2_5']:.4g} to {row['p97_5']:.4g} | not available |")
lines += ["", "## Fit on training trials (not evidence of predictive skill)", "", "| Trial | Arm | Endpoint | Observed | Fitted | Error |", "|---|---|---|---:|---:|---:|"]
for r in fit["targets"]:
    arm = r["arm"] + (f" minus {r['reference']}" if r["reference"] else "")
    lines.append(f"| {r['trial']} | {arm} | {r['endpoint']} | {r['observed']:+.2f} | {r['predicted']:+.2f} | {r['error']:+.2f} |")
Path("docs/VALIDATION.md").write_text("\n".join(lines) + "\n")
print(json.dumps(s, indent=1))
